    def __init__(self, name: str, members: Optional[list[str]] = None) -> None:
        self.name = name.strip()
        self.members = sorted(members) if members else []

    def to_dict(self) -> dict:
        return {"name": self.name, "members": self.members}

    @classmethod
    def from_dict(cls, data: dict) -> Group:
        return cls(name=data["name"], members=data.get("members", []))

    def __repr__(self) -> str:
        return f"Group(name={self.name!r}, members={len(self.members)})"
